curr_xfer value, leading to NULL pointer dereference or use-after-free.

Fixes: b4e002d8a7ce ("spi: tegra210-quad: Fix timeout handling")
Signed-off-by: Breno Leitao <leitao@debian.org>
Tested-by: Jon Hunter <jonathanh@nvidia.com>
Acked-by: Jon Hunter <jonathanh@nvidia.com>
Acked-by: Thierry Reding <treding@nvidia.com>
Link: https://patch.msgid.link/20260126-tegra_xfer-v2-4-6d2115e4f387@debian.org
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The bug is a race condition in `tegra_qspi_combined_seq_xfer` where the `curr_xfer` field is cleared without holding the spinlock (`tqspi->lock`). The interrupt handler reads `curr_xfer` without the lock to check if a transfer is in progress, so when `curr_xfer` is set to NULL outside the lock, the IRQ handler may see a partially updated or stale pointer, leading to NULL pointer dereference or use-after-free.

Here is the patch:

 static int tegra_qspi_combined_seq_xfer(struct tegra_qspi *tqspi,
 					struct spi_message *msg)
 {
 	bool is_first_msg = true;
 	struct spi_transfer *xfer;
 	struct spi_device *spi = msg->spi;
 	u8 transfer_phase = 0;
 	u32 cmd1 = 0;
 	int ret = 0;
 	u32 address_value = 0;
 	u32 cmd_config = 0, addr_config = 0;
 	u8 cmd_value = 0, val = 0;
+	unsigned long flags;

 	/* Enable Combined sequence mode */
 	val = tegra_qspi_readl(tqspi, QSPI_GLOBAL_CONFIG);
 	if (spi->mode & SPI_TPM_HW_FLOW) {
 		if (tqspi->soc_data->supports_tpm)
 			val |= QSPI_TPM_WAIT_POLL_EN;
 		else
 			return -EIO;
 	}
 	val |= QSPI_CMB_SEQ_EN;
 	tegra_qspi_writel(tqspi, val, QSPI_GLOBAL_CONFIG);
 	/* Process individual transfer list */
 	list_for_each_entry(xfer, &msg->transfers, transfer_list) {
 		switch (transfer_phase) {
 		case CMD_TRANSFER:
 			/* X1 SDR mode */
 			cmd_config = tegra_qspi_cmd_config(false, xfer->tx_nbits,
 							   xfer->len);
 			cmd_value = *((const u8 *)(xfer->tx_buf));
 			break;
 		case ADDR_TRANSFER:
 			/* X1 SDR mode */
 			addr_config = tegra_qspi_addr_config(false, xfer->tx_nbits,
 							     xfer->len);
 			address_value = *((const u32 *)(xfer->tx_buf));
 			break;
 		case DUMMY_TRANSFER:
 			if (xfer->dummy_data) {
 				tqspi->dummy_cycles = xfer->len * 8 / xfer->tx_nbits;
 				break;
 			}
 			transfer_phase++;
 			fallthrough;
 		case DATA_TRANSFER:
 			/* Program Command, Address value in register */
 			tegra_qspi_writel(tqspi, cmd_value, QSPI_CMB_SEQ_CMD);
 			tegra_qspi_writel(tqspi, address_value,
 					  QSPI_CMB_SEQ_ADDR);
 			/* Program Command and Address config in register */
 			tegra_qspi_writel(tqspi, cmd_config,
 					  QSPI_CMB_SEQ_CMD_CFG);
 			tegra_qspi_writel(tqspi, addr_config,
 					  QSPI_CMB_SEQ_ADDR_CFG);

 			reinit_completion(&tqspi->xfer_completion);
 			cmd1 = tegra_qspi_setup_transfer_one(spi, xfer,
 							     is_first_msg);
 			ret = tegra_qspi_start_transfer_one(spi, xfer,
 							    cmd1);

 			if (ret < 0) {
 				dev_err(tqspi->dev, "Failed to start transfer-one: %d\n",
 					ret);
 				return ret;
 			}

 			is_first_msg = false;
 			ret = wait_for_completion_timeout
 					(&tqspi->xfer_completion,
 					QSPI_DMA_TIMEOUT);

 			if (WARN_ON_ONCE(ret == 0)) {
 				/*
 				 * Check if hardware completed the transfer
 				 * even though interrupt was lost or delayed.
 				 * If so, process the completion and continue.
 				 */
 				ret = tegra_qspi_handle_timeout(tqspi);
 				if (ret < 0) {
 					/* Real timeout - clean up and fail */
 					dev_err(tqspi->dev, "transfer timeout\n");

 					/* Abort transfer by resetting pio/dma bit */
 					if (tqspi->is_curr_dma_xfer)
 						tegra_qspi_dma_stop(tqspi);
 					else
 						tegra_qspi_pio_stop(tqspi);

 					/* Reset controller if timeout happens */
 					tegra_qspi_reset(tqspi);

 					ret = -EIO;
 					goto exit;
 				}
 			}

 			if (tqspi->tx_status ||  tqspi->rx_status) {
 				dev_err(tqspi->dev, "QSPI Transfer failed\n");
 				tqspi->tx_status = 0;
 				tqspi->rx_status = 0;
 				ret = -EIO;
 				goto exit;
 			}
 			break;
 		default:
 			ret = -EINVAL;
 			goto exit;
 		}
 		msg->actual_length += xfer->len;
 		if (!xfer->cs_change && transfer_phase == DATA_TRANSFER) {
 			tegra_qspi_transfer_end(spi);
 			spi_transfer_delay_exec(xfer);
 		}
+		spin_lock_irqsave(&tqspi->lock, flags);
 		tqspi->curr_xfer = NULL;
+		spin_unlock_irqrestore(&tqspi->lock, flags);
 		transfer_phase++;
 	}
 	ret = 0;

 exit:
+	spin_lock_irqsave(&tqspi->lock, flags);
 	tqspi->curr_xfer = NULL;
+	spin_unlock_irqrestore(&tqspi->lock, flags);
 	msg->status = ret;

 	return ret;
 }



